package com.example.mareasv7.ui
import android.app.Application;import android.content.pm.PackageManager;import androidx.core.content.ContextCompat;import androidx.lifecycle.*;import com.example.mareasv7.data.*;import com.google.android.gms.location.*;import com.google.android.gms.tasks.CancellationTokenSource;import kotlinx.coroutines.flow.*;import kotlinx.coroutines.launch;import kotlinx.coroutines.tasks.await
sealed interface State{data object Loading:State;data class Ready(val d:Data):State;data class Error(val t:String):State}
class VM(a:Application):AndroidViewModel(a){private val gps=LocationServices.getFusedLocationProviderClient(a);private val repo=Repository();private val _s=MutableStateFlow<State>(State.Loading);val s:StateFlow<State> = _s;fun load()=viewModelScope.launch{if(ContextCompat.checkSelfPermission(getApplication(),android.Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){_s.value=State.Error("Permiso GPS no concedido");return@launch};try{val r=CurrentLocationRequest.Builder().setPriority(Priority.PRIORITY_HIGH_ACCURACY).setDurationMillis(25000).build();val l=gps.getCurrentLocation(r,CancellationTokenSource().token).await()?:error("GPS no disponible");_s.value=State.Ready(repo.load(l.latitude,l.longitude))}catch(e:Exception){_s.value=State.Error(e.message?:"Error")}}}
